public class HexByteCodec {

    private static final String DIGITS = "0123456789abcdef";

    public static int[] hexToBytes(String hex) {
        if (hex == null || hex.length() % 2 != 0) {
            return null;
        }
        int[] out = new int[hex.length() / 2];
        for (int i = 0; i < out.length; i++) {
            int high = DIGITS.indexOf(Character.toLowerCase(hex.charAt(i * 2)));
            int low = DIGITS.indexOf(Character.toLowerCase(hex.charAt(i * 2 + 1)));
            if (high < 0 || low < 0) {
                return null;
            }
            out[i] = high * 16 + low;
        }
        return out;
    }

    public static String bytesToHex(int[] values) {
        StringBuilder sb = new StringBuilder();
        for (int value : values) {
            sb.append(DIGITS.charAt((value / 16) % 16));
            sb.append(DIGITS.charAt(value % 16));
        }
        return sb.toString();
    }
}
